package com.funfriday.controller;
import com.funfriday.db.dao.LogicGridDao; import com.funfriday.db.dao.PlayerLogicGridProgressDao; import java.util.*; import lombok.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/logic-grids") @CrossOrigin(origins={"http://localhost:3000","http://funfriday.co.in","https://funfriday.co.in"},allowCredentials="true") @RequiredArgsConstructor
public class LogicGridCatalogController { private final LogicGridDao dao; private final PlayerLogicGridProgressDao progress; @GetMapping public ResponseEntity<?> list(@RequestParam(name="playerId",required=false)String playerId){try{var puzzles=dao.catalogue().stream().map(p->{var visible=new LinkedHashMap<String,Object>();visible.put("id",p.get("id"));visible.put("puzzleKey",p.get("puzzleKey"));visible.put("title",p.get("title"));visible.put("clueCount",p.get("clueCount"));return visible;}).toList();var ids=puzzles.stream().map(p->((Number)p.get("id")).longValue()).toList();return ResponseEntity.ok(Map.of("puzzles",puzzles,"progress",progress.find(playerId,ids)));}catch(Exception e){return ResponseEntity.internalServerError().body(java.util.Map.of("message","Unable to load Logic Grid puzzles."));}} }
